import {BaseAssembler} from '../../shared/infrastructure/base-assembler';
import {DemandForecast} from '../domain/model/demand-forecast.entity';
import {DemandForecastResource, DemandForecastsResponse} from './demand-forecasts-response';

/**
 * Translates demand forecasts from the API (forecasts are generated by the API, never sent by the client).
 * @author DataBit
 */
export class DemandForecastAssembler implements BaseAssembler<DemandForecast, DemandForecastResource, DemandForecastsResponse> {
  toEntityFromResource(resource: DemandForecastResource): DemandForecast {
    return new DemandForecast({
      id: resource.id, generatedAt: new Date(resource.generatedAt), confidenceScore: Number(resource.confidenceScore),
      weatherCondition: resource.weatherCondition, weatherSource: resource.weatherSource, method: resource.method,
      modelVersion: resource.modelVersion, days: resource.dataPoints
    });
  }

  toResourceFromEntity(entity: DemandForecast): DemandForecastResource {
    return {id: entity.id, generatedAt: entity.generatedAt.toISOString(), confidenceScore: entity.confidenceScore,
      weatherCondition: entity.weatherCondition, weatherSource: entity.weatherSource, method: entity.method, modelVersion: entity.modelVersion,
      dataPoints: entity.days};
  }

  toEntitiesFromResponse(response: DemandForecastsResponse): DemandForecast[] {
    return response.demandForecasts.map(resource => this.toEntityFromResource(resource));
  }
}
